def _normalize_argv(argv: list[str]) -> list[str]:
    front: list[str] = []
    rest: list[str] = []
    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg == "--":
            rest.extend(argv[i:])
            break
        if arg == "--max-segment-bytes":
            if i + 1 < len(argv):
                front.extend([arg, argv[i + 1]])
                i += 2
            else:
                front.append(arg)
                i += 1
        elif arg.startswith("--max-segment-bytes="):
            front.append(arg)
            i += 1
        else:
            rest.append(arg)
            i += 1
    return front + rest

